engine.runWorkflow:
function runWorkflow(workflow, initialCtx, providers) {
  // ── Variable interpolation: {{step_id.field}} + {{cond ? t : f}} ──
  function _resolvePath(path, ctx) {
    var parts = path.split(".");
    var cur = ctx;
    for (var i = 0; i < parts.length; i++) {
      if (cur == null) return null;
      cur = cur[parts[i]];
    }
    return cur;
  }
  function _interpolate(template, ctx) {
    if (template == null) return "";
    return String(template).replace(/\{\{([^}]+)\}\}/g, function (_, expr) {
      expr = expr.trim();
      var ternary = expr.match(/^([^?]+?)\s*\?\s*([^:]*?)\s*:\s*(.*)$/);
      if (ternary) {
        var condVal = _resolvePath(ternary[1].trim(), ctx);
        var truthy = !!condVal && condVal !== "false" && condVal !== "0";
        return truthy ? ternary[2].trim() : ternary[3].trim();
      }
      var val = _resolvePath(expr, ctx);
      if (val == null) return "—";
      if (Array.isArray(val)) return val.length ? val.join(", ") : "—";
      if (typeof val === "object") {
        try { return JSON.stringify(val); } catch (_e) { return "—"; }
      }
      return String(val);
    });
  }
  // ── AI prompt assembly + JSON parse ─────────────────────────────
  function _buildAskAiPrompt(step, userPrompt, ctx) {
    var docBlock = ctx.docText
      ? "\n\nDOCUMENT TEXT:\n---\n" + String(ctx.docText).substring(0, 200000) + "\n---\n"
      : "";
    var schemaHint = step.schema
      ? "\n\nReturn ONLY raw JSON matching this shape (no preamble, no markdown):\n" + JSON.stringify(step.schema)
      : "\n\nReturn ONLY raw JSON. No preamble.";
    return [
      "You are an AI legal assistant helping Colgate-Palmolive's legal team.",
      "Perspective: when the user says 'we', 'us', 'our' they mean Colgate.",
      "TASK: " + userPrompt,
      docBlock,
      schemaHint,
    ].join("\n");
  }
  function _safeParseJson(raw) {
    if (raw == null) return null;
    if (typeof raw !== "string") return raw;
    var s = raw.trim()
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```\s*$/, "");
    try { return JSON.parse(s); } catch (_e) {
      var m = s.match(/\{[\s\S]*\}/);
      if (m) { try { return JSON.parse(m[0]); } catch (_e2) {} }
      return { _raw: s };
    }
  }
  // ── Step handlers ────────────────────────────────────────────────
  function _stepAskAi(step, ctx) {
    var ai = providers.ai;
    if (!ai) return Promise.reject(new Error("ai provider missing"));
    var interpolated = _interpolate(step.prompt, ctx);
    var fullPrompt = _buildAskAiPrompt(step, interpolated, ctx);
    if (typeof ai.completeJSON === "function") {
      return ai.completeJSON(fullPrompt, step.schema || null);
    }
    if (typeof ai.complete === "function") {
      return ai.complete(fullPrompt).then(_safeParseJson);
    }
    return Promise.reject(new Error("ai.completeJSON or ai.complete required"));
  }
  function _stepReadDoc(step, ctx) {
    var field = step.field || "docText";
    var out = {};
    out[field] = ctx[field] != null ? ctx[field] : null;
    if (field === "hasRedlines")  out.hasRedlines  = !!ctx.hasRedlines;
    if (field === "hasComments")  out.hasComments  = !!ctx.hasComments;
    if (field === "commentCount") out.commentCount = ctx.commentCount || 0;
    return Promise.resolve(out);
  }
  function _stepExtract(step, ctx) {
    var text = String(ctx.docText || "");
    var pattern = step.pattern || "";
    try {
      var re = new RegExp(pattern, step.flags || "gi");
      var matches = text.match(re) || [];
      return Promise.resolve({ count: matches.length, matches: matches.slice(0, 50) });
    } catch (e) {
      return Promise.resolve({ error: "Invalid pattern: " + e.message, count: 0, matches: [] });
    }
  }
  function _stepTransform(step, ctx) {
    var expr = step.expression || "";
    try {
      var fn = new Function("ctx", "return (" + expr + ");");
      return Promise.resolve({ value: fn(ctx) });
    } catch (e) { return Promise.resolve({ error: e.message }); }
  }
  function _stepBranch(step, ctx) {
    var expr = step.condition || "false";
    try {
      var fn = new Function("ctx", "return !!(" + expr + ");");
      var truthy = fn(ctx);
      return Promise.resolve({ taken: truthy ? "then" : "else", condition: expr });
    } catch (e) { return Promise.resolve({ taken: "else", error: e.message }); }
  }
  function _stepRunTool(step, ctx) {
    var dispatch = providers.dispatch;
    if (typeof dispatch !== "function") return Promise.resolve({ error: "dispatch unavailable" });
    var toolId = step.tool;
    var channel = step.channel || "open";
    var args = step.args || {};
    try {
      var result = dispatch(toolId, channel, _interpolate(JSON.stringify(args), ctx));
      return Promise.resolve(result || { dispatched: true });
    } catch (e) { return Promise.resolve({ error: e.message }); }
  }
  function _stepEmail(step, ctx) {
    return Promise.resolve({
      to:      _interpolate(step.to || "", ctx),
      subject: _interpolate(step.subject || "", ctx),
      body:    _interpolate(step.body || "", ctx),
    });
  }
  function _executeStep(step, ctx) {
    switch (step.type) {
      case "ask_ai":    return _stepAskAi(step, ctx);
      case "read_doc":  return _stepReadDoc(step, ctx);
      case "extract":   return _stepExtract(step, ctx);
      case "transform": return _stepTransform(step, ctx);
      case "branch":    return _stepBranch(step, ctx);
      case "run_tool":  return _stepRunTool(step, ctx);
      case "email":     return _stepEmail(step, ctx);
      case "report":    return Promise.resolve({ rendered: true });
      default:          return Promise.reject(new Error("Unknown step type: " + step.type));
    }
  }
  // ── Main runner ─────────────────────────────────────────────────
  var ctx = Object.assign({}, initialCtx || {});
  var steps = workflow.steps || [];
  var onProgress = (providers && providers.onProgress) || function () {};
  var p = Promise.resolve();
  var results = [];
  steps.forEach(function (step, idx) {
    p = p.then(function () {
      if (providers.cancelled && providers.cancelled()) {
        throw new Error("Cancelled");
      }
      onProgress({ stepIdx: idx, step: step, status: "running" });
      return _executeStep(step, ctx).then(function (out) {
        ctx[step.id] = out;
        results.push({ step: step, output: out });
        onProgress({ stepIdx: idx, step: step, status: "done", output: out });
      }).catch(function (err) {
        var errOut = { error: (err && err.message) || String(err) };
        ctx[step.id] = errOut;
        results.push({ step: step, output: errOut, error: true });
        onProgress({ stepIdx: idx, step: step, status: "error", output: errOut });
      });
    });
  });
  return p.then(function () {
    return { context: ctx, results: results, completedAt: Date.now() };
  });
}

// ─── buildReport — final structured report. Own copy of helpers. ────

engine.buildReport:
function buildReport(workflow, ctx) {
  function _resolvePath(path, ctx) {
    var parts = path.split(".");
    var cur = ctx;
    for (var i = 0; i < parts.length; i++) {
      if (cur == null) return null;
      cur = cur[parts[i]];
    }
    return cur;
  }
  function _interpolate(template, ctx) {
    if (template == null) return "";
    return String(template).replace(/\{\{([^}]+)\}\}/g, function (_, expr) {
      expr = expr.trim();
      var ternary = expr.match(/^([^?]+?)\s*\?\s*([^:]*?)\s*:\s*(.*)$/);
      if (ternary) {
        var condVal = _resolvePath(ternary[1].trim(), ctx);
        var truthy = !!condVal && condVal !== "false" && condVal !== "0";
        return truthy ? ternary[2].trim() : ternary[3].trim();
      }
      var val = _resolvePath(expr, ctx);
      if (val == null) return "—";
      if (Array.isArray(val)) return val.length ? val.join(", ") : "—";
      if (typeof val === "object") {
        try { return JSON.stringify(val); } catch (_e) { return "—"; }
      }
      return String(val);
    });
  }
  var report = workflow.report || {};
  var title = report.title || workflow.name || "Workflow Result";
  var sections = (report.sections || []).map(function (s) {
    return {
      label:    s.label || "",
      value:    _interpolate(s.value, ctx),
      note:     _interpolate(s.note || "", ctx),
      emphasis: !!s.emphasis,
    };
  });
  var listItems = null;
  if (report.listFromStep) {
    var spec = report.listFromStep;
    var arr = ctx[spec.stepId] && ctx[spec.stepId][spec.arrayField];
    if (Array.isArray(arr)) {
      var tpl = spec.itemTemplate || {};
      listItems = arr.map(function (item) {
        var node = { _raw: item };
        if (tpl.titleField)    node.title    = item[tpl.titleField];
        if (tpl.metaField)     node.meta     = item[tpl.metaField];
        if (tpl.badgeField)    node.badge    = item[tpl.badgeField];
        if (tpl.severityField) node.severity = item[tpl.severityField];
        if (tpl.bodyField)     node.body     = item[tpl.bodyField];
        return node;
      });
    }
  }
  return { title: title, sections: sections, listItems: listItems };
}

// ─── validateWorkflow — standalone, no helpers needed ──────────────

engine.validateWorkflow:
function validateWorkflow(wf) {
  var errs = [];
  if (!wf) { errs.push("Workflow is empty"); return errs; }
  if (!wf.id || !/^[a-z][a-z0-9_]*$/.test(wf.id)) errs.push("id must be lowercase letter-leading identifier");
  if (!wf.name) errs.push("name is required");
  if (!Array.isArray(wf.steps) || !wf.steps.length) errs.push("at least one step required");
  (wf.steps || []).forEach(function (s, i) {
    if (!s.id) errs.push("step " + i + ": id required");
    if (!s.type) errs.push("step " + i + ": type required");
    if (s.type === "ask_ai" && !s.prompt) errs.push("step " + i + ": prompt required for ask_ai");
  });
  return errs;
}

view.renderWorkflowLibrary:
function renderWorkflowLibrary(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _icon(s) { return _esc(s || "📄"); }
  function _fmtWhen(ts) {
    if (!ts) return "";
    try {
      return new Date(ts).toLocaleString("en-US", {
        month: "short", day: "numeric", hour: "numeric", minute: "2-digit",
      });
    } catch (_) { return ""; }
  }
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var starters = opts.starters || [];
  var userWfs  = opts.userWorkflows || [];
  var lastRuns = opts.lastRuns || {};
  var onRun    = opts.onRun || function () {};
  var onEdit   = opts.onEdit || function () {};
  var onClone  = opts.onClone || function () {};
  var onDelete = opts.onDelete || function () {};
  var onNew    = opts.onNew  || function () {};
  var onBack   = opts.onBack || function () {};

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_wf_root";
  root.innerHTML =
    '<div class="_eli3_wf_header">' +
      '<div class="_eli3_wf_header_eyebrow">⚡ Workflow Creator · ALPHA</div>' +
      '<h1 class="_eli3_wf_header_title">Workflows</h1>' +
      '<div class="_eli3_wf_header_sub">Multi-step legal analyses you can run on the current document. Each workflow walks a sequence of AI questions, doc reads, and synthesis steps — then returns a structured report.</div>' +
      '<div class="_eli3_wf_header_actions">' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_gold" data-act="new">+ Build New Workflow</button>' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_ghost" data-act="back">← Back to Dashboard</button>' +
      '</div>' +
    '</div>' +
    '<div class="_eli3_wf_body">' +
      // STARTERS
      '<div class="_eli3_wf_section_label">' +
        '<span>Starter Library</span>' +
        '<span class="_eli3_wf_count_chip">' + starters.length + '</span>' +
      '</div>' +
      '<div data-zone="starters"></div>' +
      // USER WORKFLOWS
      '<div class="_eli3_wf_section_label" style="margin-top:24px">' +
        '<span>Your Workflows</span>' +
        '<span class="_eli3_wf_count_chip">' + userWfs.length + '</span>' +
      '</div>' +
      '<div data-zone="user"></div>' +
    '</div>';
  mount.appendChild(root);

  // Hide section labels when empty (no count of zero)
  if (!userWfs.length) {
    var emptyEl = document.createElement("div");
    emptyEl.className = "_eli3_wf_empty";
    emptyEl.innerHTML =
      '<div class="_eli3_wf_empty_icon">🛠</div>' +
      '<div class="_eli3_wf_empty_msg">No custom workflows yet. Click <strong>+ Build New Workflow</strong> to create one, or clone a starter to customize.</div>';
    root.querySelector('[data-zone="user"]').appendChild(emptyEl);
  }

  function _cardFor(wf, isUser) {
    var lastTs = lastRuns[wf.id];
    var card = document.createElement("div");
    card.className = "_eli3_wf_card" + (isUser ? " _eli3_wf_card_user" : "");
    var tagsHtml = (wf.tags || []).slice(0, 3).map(function (t) {
      return '<span class="_eli3_wf_tag">' + _esc(t) + '</span>';
    }).join("");
    var typesHtml = (wf.agreementTypes && wf.agreementTypes.length)
      ? '<span>📄 ' + _esc(wf.agreementTypes.slice(0, 2).join(", ")) + (wf.agreementTypes.length > 2 ? " +" + (wf.agreementTypes.length - 2) : "") + '</span>'
      : '';
    var lastHtml = lastTs
      ? '<span>🕓 Last run: ' + _esc(_fmtWhen(lastTs)) + '</span>'
      : '';
    card.innerHTML =
      '<div class="_eli3_wf_card_head">' +
        '<div class="_eli3_wf_card_icon">' + _icon(wf.icon) + '</div>' +
        '<div class="_eli3_wf_card_titles">' +
          '<div class="_eli3_wf_card_name">' + _esc(wf.name) + '</div>' +
          '<div class="_eli3_wf_card_desc">' + _esc(wf.description || "") + '</div>' +
          (tagsHtml ? '<div style="margin-top:8px">' + tagsHtml + '</div>' : '') +
        '</div>' +
      '</div>' +
      '<div class="_eli3_wf_card_meta">' +
        '<span>⚙ ' + (wf.steps || []).length + ' step' + ((wf.steps || []).length === 1 ? '' : 's') + '</span>' +
        typesHtml +
        lastHtml +
      '</div>' +
      '<div class="_eli3_wf_card_actions">' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_gold" data-act="run">▶ Run</button>' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_platinum" data-act="edit">' + (isUser ? '✎ Edit' : '👁 View') + '</button>' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_platinum" data-act="clone">⎘ Clone</button>' +
        (isUser ? '<button class="_eli3_wf_btn _eli3_wf_btn_danger" data-act="delete">🗑</button>' : '') +
      '</div>';
    card.querySelector('[data-act="run"]').onclick = function () { onRun(wf, isUser); };
    card.querySelector('[data-act="edit"]').onclick = function () { onEdit(wf, isUser); };
    card.querySelector('[data-act="clone"]').onclick = function () { onClone(wf); };
    var del = card.querySelector('[data-act="delete"]');
    if (del) del.onclick = function () { onDelete(wf); };
    return card;
  }
  var starterZone = root.querySelector('[data-zone="starters"]');
  starters.forEach(function (wf) { starterZone.appendChild(_cardFor(wf, false)); });
  var userZone = root.querySelector('[data-zone="user"]');
  userWfs.forEach(function (wf) { userZone.appendChild(_cardFor(wf, true)); });

  root.querySelector('[data-act="new"]').onclick = onNew;
  root.querySelector('[data-act="back"]').onclick = onBack;
}

// ─── Renderer: running view ──────────────────────────────────────────
// Called on workflow start. Returns a handle with updateStep(stepIdx,
// state, output) so the runner can drive the UI as it progresses.

view.renderWorkflowRunner:
function renderWorkflowRunner(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _icon(s) { return _esc(s || "📄"); }
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return null;
  var workflow = opts.workflow;
  var onCancel = opts.onCancel || function () {};

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_wf_root";
  root.innerHTML =
    '<div class="_eli3_wf_header">' +
      '<div class="_eli3_wf_header_eyebrow">⚙ Running Workflow</div>' +
      '<h1 class="_eli3_wf_header_title">' + _icon(workflow.icon) + '  ' + _esc(workflow.name) + '</h1>' +
      '<div class="_eli3_wf_header_sub">' + _esc(workflow.description || "") + '</div>' +
      '<div class="_eli3_wf_header_actions">' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_ghost" data-act="cancel">✕ Cancel</button>' +
      '</div>' +
    '</div>' +
    '<div class="_eli3_wf_body">' +
      '<div class="_eli3_wf_runner">' +
        '<div class="_eli3_wf_runner_title">Pipeline progress</div>' +
        '<div class="_eli3_wf_runner_progress" data-progress>Step 1 of ' + (workflow.steps || []).length + '</div>' +
        '<div data-zone="steps"></div>' +
      '</div>' +
    '</div>';
  mount.appendChild(root);
  var stepsZone = root.querySelector('[data-zone="steps"]');
  var progEl = root.querySelector('[data-progress]');

  var stepEls = [];
  (workflow.steps || []).forEach(function (step, i) {
    var row = document.createElement("div");
    row.className = "_eli3_wf_step_row";
    row.innerHTML =
      '<div class="_eli3_wf_step_indicator">' + (i + 1) + '</div>' +
      '<div class="_eli3_wf_step_name">' + _esc(step.name || step.id) + '</div>' +
      '<div class="_eli3_wf_step_type">' + _esc(step.type) + '</div>';
    stepsZone.appendChild(row);
    stepEls.push(row);
  });

  root.querySelector('[data-act="cancel"]').onclick = onCancel;

  return {
    updateStep: function (idx, state, _output) {
      var el = stepEls[idx];
      if (!el) return;
      el.classList.remove("_eli3_wf_step_done", "_eli3_wf_step_running", "_eli3_wf_step_error");
      if (state === "running") el.classList.add("_eli3_wf_step_running");
      else if (state === "done") el.classList.add("_eli3_wf_step_done");
      else if (state === "error") el.classList.add("_eli3_wf_step_error");
      // Update progress label
      if (state === "running") {
        progEl.textContent = "Step " + (idx + 1) + " of " + stepEls.length + " · " + ((opts.workflow.steps[idx].name) || "Running…");
      } else if (state === "done" && idx === stepEls.length - 1) {
        progEl.textContent = "Finalizing report…";
      }
    },
  };
}

// ─── Renderer: result view ───────────────────────────────────────────

view.renderWorkflowResult:
function renderWorkflowResult(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _icon(s) { return _esc(s || "📄"); }
  function _fmtWhen(ts) {
    if (!ts) return "";
    try {
      return new Date(ts).toLocaleString("en-US", {
        month: "short", day: "numeric", hour: "numeric", minute: "2-digit",
      });
    } catch (_) { return ""; }
  }
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var workflow = opts.workflow;
  var report   = opts.report || { title: workflow.name, sections: [], listItems: null };
  var results  = opts.results || [];
  var ctx      = opts.context || {};
  var onBack   = opts.onBack  || function () {};
  var onRerun  = opts.onRerun || function () {};
  var onCopy   = opts.onCopy  || function () {};

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_wf_root";
  root.innerHTML =
    '<div class="_eli3_wf_header">' +
      '<div class="_eli3_wf_header_eyebrow">✓ Workflow Complete</div>' +
      '<h1 class="_eli3_wf_header_title">' + _icon(workflow.icon) + '  ' + _esc(report.title) + '</h1>' +
      '<div class="_eli3_wf_header_sub">Ran ' + (workflow.steps || []).length + ' step' + ((workflow.steps || []).length === 1 ? '' : 's') + ' at ' + _esc(_fmtWhen(opts.completedAt)) + '</div>' +
      '<div class="_eli3_wf_header_actions">' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_gold" data-act="rerun">↻ Re-run</button>' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_ghost" data-act="copy">📋 Copy Report</button>' +
        '<button class="_eli3_wf_btn _eli3_wf_btn_ghost" data-act="back">← Library</button>' +
      '</div>' +
    '</div>' +
    '<div class="_eli3_wf_body">' +
      '<div data-zone="sections"></div>' +
      '<div data-zone="list"></div>' +
      '<div data-zone="raw"></div>' +
    '</div>';
  mount.appendChild(root);

  var secZone = root.querySelector('[data-zone="sections"]');
  (report.sections || []).forEach(function (s) {
    var el = document.createElement("div");
    el.className = "_eli3_wf_section" + (s.emphasis ? " _eli3_wf_section_emphasis" : "");
    el.innerHTML =
      '<div class="_eli3_wf_section_lbl">' + _esc(s.label) + '</div>' +
      '<div class="_eli3_wf_section_val">' + _esc(s.value) + '</div>' +
      (s.note ? '<div class="_eli3_wf_section_note">' + _esc(s.note) + '</div>' : '');
    secZone.appendChild(el);
  });

  var listZone = root.querySelector('[data-zone="list"]');
  if (report.listItems && report.listItems.length) {
    var heading = document.createElement("div");
    heading.className = "_eli3_wf_section_label";
    heading.style.marginTop = "16px";
    heading.innerHTML = '<span>Details</span><span class="_eli3_wf_count_chip">' + report.listItems.length + '</span>';
    listZone.appendChild(heading);
    report.listItems.forEach(function (item) {
      var el = document.createElement("div");
      el.className = "_eli3_wf_list_item";
      var sev = item.severity ? '<div class="_eli3_wf_list_severity" data-sev="' + _esc(item.severity) + '"></div>' : '<div class="_eli3_wf_list_severity"></div>';
      el.innerHTML =
        sev +
        '<div class="_eli3_wf_list_body">' +
          '<div class="_eli3_wf_list_head">' +
            '<div class="_eli3_wf_list_title">' + _esc(item.title || "—") + '</div>' +
            (item.badge != null ? '<div class="_eli3_wf_list_badge">' + _esc(item.badge) + '</div>' : '') +
          '</div>' +
          (item.meta ? '<div class="_eli3_wf_list_meta">' + _esc(item.meta) + '</div>' : '') +
          (item.body ? '<div class="_eli3_wf_list_text">' + _esc(item.body) + '</div>' : '') +
        '</div>';
      listZone.appendChild(el);
    });
  }

  // Raw output discloser at bottom for debugging.
  var rawZone = root.querySelector('[data-zone="raw"]');
  var disc = document.createElement("button");
  disc.className = "_eli3_wf_disclose";
  disc.textContent = "▸ Show raw step outputs";
  var rawEl = document.createElement("div");
  rawEl.className = "_eli3_wf_raw_output";
  rawEl.style.display = "none";
  try {
    rawEl.textContent = JSON.stringify(results.map(function (r) {
      return { step: r.step.id, type: r.step.type, output: r.output };
    }), null, 2);
  } catch (_) { rawEl.textContent = "(could not serialize)"; }
  disc.onclick = function () {
    var open = rawEl.style.display !== "none";
    rawEl.style.display = open ? "none" : "block";
    disc.textContent = open ? "▸ Show raw step outputs" : "▾ Hide raw step outputs";
  };
  rawZone.appendChild(disc);
  rawZone.appendChild(rawEl);

  root.querySelector('[data-act="back"]').onclick = onBack;
  root.querySelector('[data-act="rerun"]').onclick = onRerun;
  root.querySelector('[data-act="copy"]').onclick = function () { onCopy(report); };
}

// ─── Renderer: editor view (v2 form-based, no drag yet) ──────────────

view.renderWorkflowEditor:
function renderWorkflowEditor(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _icon(s) { return _esc(s || "📄"); }
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var workflow = opts.workflow ? JSON.parse(JSON.stringify(opts.workflow)) : _emptyWorkflow();
  var readOnly = !!opts.readOnly;
  var onSave   = opts.onSave   || function () {};
  var onCancel = opts.onCancel || function () {};
  var onTestStep = opts.onTestStep || function () {};

  function _emptyWorkflow() {
    return {
      id: "untitled_workflow_" + Date.now(),
      name: "Untitled Workflow",
      icon: "📋",
      description: "",
      tags: [],
      steps: [],
      report: { title: "", sections: [] },
    };
  }

  function _rerender() {
    mount.innerHTML = "";
    var root = document.createElement("div");
    root.className = "_eli3_wf_root";
    root.innerHTML =
      '<div class="_eli3_wf_header">' +
        '<div class="_eli3_wf_header_eyebrow">' + (readOnly ? '👁 Viewing Workflow' : '✎ Editing Workflow') + '</div>' +
        '<h1 class="_eli3_wf_header_title">' + _icon(workflow.icon) + '  ' + _esc(workflow.name || "Untitled") + '</h1>' +
        '<div class="_eli3_wf_header_sub">' + (readOnly ? "Starter workflows can't be edited — clone to customize." : "Edit metadata, add/remove steps, build the report. Save to use.") + '</div>' +
        '<div class="_eli3_wf_header_actions">' +
          (readOnly ? '' : '<button class="_eli3_wf_btn _eli3_wf_btn_gold" data-act="save">💾 Save</button>') +
          '<button class="_eli3_wf_btn _eli3_wf_btn_ghost" data-act="cancel">' + (readOnly ? '← Library' : '✕ Cancel') + '</button>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_wf_body">' +
        // METADATA
        '<div class="_eli3_wf_editor_section">' +
          '<div class="_eli3_wf_section_label" style="margin:0 0 10px">Metadata</div>' +
          _field("Name", "input", "name", workflow.name, readOnly) +
          _field("ID", "input", "id", workflow.id, readOnly) +
          _field("Icon (emoji)", "input", "icon", workflow.icon, readOnly) +
          _field("Description", "textarea", "description", workflow.description, readOnly) +
          _field("Tags (comma-separated)", "input", "tags", (workflow.tags || []).join(", "), readOnly) +
        '</div>' +
        // STEPS
        '<div class="_eli3_wf_section_label" style="margin-top:16px"><span>Steps</span><span class="_eli3_wf_count_chip">' + (workflow.steps || []).length + '</span></div>' +
        '<div data-zone="steps"></div>' +
        (readOnly ? '' : '<div class="_eli3_wf_add_step" data-act="add-step">+ Add Step</div>') +
        // REPORT
        '<div class="_eli3_wf_section_label" style="margin-top:24px">Report</div>' +
        '<div class="_eli3_wf_editor_section">' +
          _field("Report title", "input", "report.title", (workflow.report || {}).title || workflow.name, readOnly) +
        '</div>' +
      '</div>';
    mount.appendChild(root);

    // Wire metadata fields.
    function _wireField(key, transform) {
      var el = root.querySelector('[data-field="' + key + '"]');
      if (!el) return;
      el.oninput = function () {
        var v = transform ? transform(el.value) : el.value;
        var path = key.split(".");
        if (path.length === 1) workflow[path[0]] = v;
        else if (path.length === 2) {
          workflow[path[0]] = workflow[path[0]] || {};
          workflow[path[0]][path[1]] = v;
        }
      };
    }
    _wireField("name");
    _wireField("id");
    _wireField("icon");
    _wireField("description");
    _wireField("tags", function (v) {
      return v.split(",").map(function (t) { return t.trim(); }).filter(Boolean);
    });
    _wireField("report.title");

    // Render each step.
    var stepsZone = root.querySelector('[data-zone="steps"]');
    (workflow.steps || []).forEach(function (step, idx) {
      var card = _renderStepCard(step, idx, workflow, readOnly, function _onChange() {
        // mutated in place; nothing to do here, save will pick it up
      }, function _onDelete() {
        workflow.steps.splice(idx, 1);
        _rerender();
      }, function _onMoveUp() {
        if (idx > 0) {
          var tmp = workflow.steps[idx - 1];
          workflow.steps[idx - 1] = workflow.steps[idx];
          workflow.steps[idx] = tmp;
          _rerender();
        }
      }, function _onMoveDown() {
        if (idx < workflow.steps.length - 1) {
          var tmp2 = workflow.steps[idx + 1];
          workflow.steps[idx + 1] = workflow.steps[idx];
          workflow.steps[idx] = tmp2;
          _rerender();
        }
      }, function _onTest() {
        onTestStep(step, workflow);
      });
      stepsZone.appendChild(card);
    });

    if (!readOnly) {
      var addBtn = root.querySelector('[data-act="add-step"]');
      if (addBtn) {
        addBtn.onclick = function () {
          workflow.steps = workflow.steps || [];
          workflow.steps.push({
            id: "step_" + (workflow.steps.length + 1),
            type: "ask_ai",
            name: "New Step",
            prompt: "",
            schema: null,
          });
          _rerender();
        };
      }
    }
    root.querySelector('[data-act="cancel"]').onclick = onCancel;
    var saveBtn = root.querySelector('[data-act="save"]');
    if (saveBtn) saveBtn.onclick = function () { onSave(workflow); };
  }

  _rerender();

  function _field(label, type, key, val, readOnly) {
    var control = "";
    if (type === "textarea") {
      control = '<textarea class="_eli3_wf_editor_textarea" data-field="' + key + '" rows="3"' + (readOnly ? " disabled" : "") + '>' + _esc(val || "") + '</textarea>';
    } else if (type === "select") {
      control = '<select class="_eli3_wf_editor_select" data-field="' + key + '"' + (readOnly ? " disabled" : "") + '>' + (val || "") + '</select>';
    } else {
      control = '<input class="_eli3_wf_editor_input" data-field="' + key + '" value="' + _esc(val || "") + '"' + (readOnly ? " disabled" : "") + ' />';
    }
    return '<label class="_eli3_wf_editor_label">' + _esc(label) + '</label>' + control + '<div style="height:10px"></div>';
  }

  function _renderStepCard(step, idx, wf, readOnly, onChange, onDelete, onUp, onDown, onTest) {
    var card = document.createElement("div");
    card.className = "_eli3_wf_step_card _eli3_wf_step_" + (step.type || "ask_ai");
    var availableVars = wf.steps.slice(0, idx).map(function (s) {
      return "{{" + s.id + ".*}}";
    }).join("  ");
    var typeOptions = ["ask_ai", "read_doc", "extract", "transform", "branch", "run_tool", "email", "report"]
      .map(function (t) { return '<option value="' + t + '"' + (step.type === t ? ' selected' : '') + '>' + t + '</option>'; })
      .join("");
    var fieldsHtml = "";
    if (step.type === "ask_ai") {
      fieldsHtml =
        '<div class="_eli3_wf_step_field">' +
          '<span class="_eli3_wf_step_field_lbl">Prompt</span>' +
          '<textarea class="_eli3_wf_editor_textarea" data-step-field="prompt" rows="4"' + (readOnly ? " disabled" : "") + '>' + _esc(step.prompt || "") + '</textarea>' +
        '</div>' +
        (availableVars ? '<div class="_eli3_wf_vars_hint">Available variables: ' + availableVars.split("  ").map(function (v) { return '<code>' + _esc(v) + '</code>'; }).join(" ") + '</div>' : '') +
        '<div class="_eli3_wf_step_field">' +
          '<span class="_eli3_wf_step_field_lbl">Output schema (JSON)</span>' +
          '<textarea class="_eli3_wf_editor_textarea" data-step-field="schema" rows="3"' + (readOnly ? " disabled" : "") + ' placeholder=\'{ "field": "string" }\'>' + _esc(step.schema ? JSON.stringify(step.schema, null, 2) : "") + '</textarea>' +
        '</div>';
    } else if (step.type === "read_doc") {
      fieldsHtml =
        '<div class="_eli3_wf_step_field">' +
          '<span class="_eli3_wf_step_field_lbl">Field to read</span>' +
          '<select class="_eli3_wf_editor_select" data-step-field="field"' + (readOnly ? " disabled" : "") + '>' +
            ['docText', 'docHash', 'hasRedlines', 'hasComments', 'commentCount', 'agreementType', 'selectionText']
              .map(function (f) { return '<option value="' + f + '"' + (step.field === f ? ' selected' : '') + '>' + f + '</option>'; })
              .join("") +
          '</select>' +
        '</div>';
    } else if (step.type === "extract") {
      fieldsHtml =
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">Regex pattern</span><input class="_eli3_wf_editor_input" data-step-field="pattern" value="' + _esc(step.pattern || "") + '"' + (readOnly ? " disabled" : "") + '></div>' +
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">Flags</span><input class="_eli3_wf_editor_input" data-step-field="flags" value="' + _esc(step.flags || "gi") + '"' + (readOnly ? " disabled" : "") + '></div>';
    } else if (step.type === "transform") {
      fieldsHtml =
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">JS expression (ctx is available)</span><textarea class="_eli3_wf_editor_textarea" data-step-field="expression" rows="3"' + (readOnly ? " disabled" : "") + '>' + _esc(step.expression || "") + '</textarea></div>';
    } else if (step.type === "branch") {
      fieldsHtml =
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">Condition (JS expression, ctx available)</span><input class="_eli3_wf_editor_input" data-step-field="condition" value="' + _esc(step.condition || "") + '"' + (readOnly ? " disabled" : "") + '></div>';
    } else if (step.type === "run_tool") {
      fieldsHtml =
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">Tool ID</span><input class="_eli3_wf_editor_input" data-step-field="tool" value="' + _esc(step.tool || "") + '"' + (readOnly ? " disabled" : "") + '></div>' +
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">Channel</span><input class="_eli3_wf_editor_input" data-step-field="channel" value="' + _esc(step.channel || "open") + '"' + (readOnly ? " disabled" : "") + '></div>';
    } else if (step.type === "email") {
      fieldsHtml =
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">To</span><input class="_eli3_wf_editor_input" data-step-field="to" value="' + _esc(step.to || "") + '"' + (readOnly ? " disabled" : "") + '></div>' +
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">Subject</span><input class="_eli3_wf_editor_input" data-step-field="subject" value="' + _esc(step.subject || "") + '"' + (readOnly ? " disabled" : "") + '></div>' +
        '<div class="_eli3_wf_step_field"><span class="_eli3_wf_step_field_lbl">Body (Markdown OK)</span><textarea class="_eli3_wf_editor_textarea" data-step-field="body" rows="4"' + (readOnly ? " disabled" : "") + '>' + _esc(step.body || "") + '</textarea></div>';
    }

    card.innerHTML =
      '<div class="_eli3_wf_step_card_head">' +
        '<div class="_eli3_wf_step_idx">' + (idx + 1) + '</div>' +
        '<input class="_eli3_wf_editor_input _eli3_wf_step_card_name" data-step-field="name" value="' + _esc(step.name || step.id || "") + '"' + (readOnly ? " disabled" : "") + ' style="border:none;background:transparent;padding:0;font-weight:600;font-size:13px">' +
        '<div class="_eli3_wf_step_card_actions">' +
          (readOnly ? '' :
            '<button class="_eli3_wf_step_iconbtn" data-act="up" title="Move up">↑</button>' +
            '<button class="_eli3_wf_step_iconbtn" data-act="down" title="Move down">↓</button>' +
            '<button class="_eli3_wf_step_iconbtn" data-act="test" title="Test step">▶</button>' +
            '<button class="_eli3_wf_step_iconbtn _eli3_wf_step_iconbtn_danger" data-act="delete" title="Delete">🗑</button>'
          ) +
        '</div>' +
      '</div>' +
      '<div class="_eli3_wf_step_field">' +
        '<span class="_eli3_wf_step_field_lbl">Step ID</span>' +
        '<input class="_eli3_wf_editor_input" data-step-field="id" value="' + _esc(step.id || "") + '"' + (readOnly ? " disabled" : "") + '>' +
      '</div>' +
      '<div class="_eli3_wf_step_field">' +
        '<span class="_eli3_wf_step_field_lbl">Type</span>' +
        '<select class="_eli3_wf_editor_select" data-step-field="type"' + (readOnly ? " disabled" : "") + '>' + typeOptions + '</select>' +
      '</div>' +
      fieldsHtml;

    // Wire field changes.
    card.querySelectorAll('[data-step-field]').forEach(function (el) {
      var key = el.getAttribute("data-step-field");
      el.oninput = el.onchange = function () {
        if (key === "schema") {
          try { step[key] = el.value ? JSON.parse(el.value) : null; } catch (_) { /* invalid until valid */ }
        } else if (key === "type") {
          step[key] = el.value;
          _rerender();   // re-render so fields swap per type
          return;
        } else {
          step[key] = el.value;
        }
        onChange();
      };
    });

    if (!readOnly) {
      card.querySelector('[data-act="delete"]').onclick = onDelete;
      card.querySelector('[data-act="up"]').onclick = onUp;
      card.querySelector('[data-act="down"]').onclick = onDown;
      card.querySelector('[data-act="test"]').onclick = onTest;
    }
    return card;
  }
}

jsonTools.init:
function init(eli) {
  // Defensive: kernel passes eli; some loaders fall through to window.
  eli = eli || window.eli;
  if (!eli || !eli.register) return;
  // Multi-file bundles expose engine.js + view.js functions on the
  // bundle record's _eliEngineFns / _eliViewFns objects — NOT on
  // window. (Same pattern ask_eli + build_draft + others use.)
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded["workflow_creator"];
  if (!bundle) {
    try { eli.log.event("workflow_creator.boot_no_bundle"); } catch (_) {}
    return;
  }
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns   || {};
  var _getStarterWorkflows = efns.getStarterWorkflows;
  var _runWorkflow         = efns.runWorkflow;
  var _buildReport         = efns.buildReport;
  var _validateWorkflow    = efns.validateWorkflow;
  var _renderLibrary       = vfns.renderWorkflowLibrary;
  var _renderRunner        = vfns.renderWorkflowRunner;
  var _renderResult        = vfns.renderWorkflowResult;
  var _renderEditor        = vfns.renderWorkflowEditor;

  if (!_getStarterWorkflows || !_runWorkflow || !_renderLibrary) {
    try {
      eli.log.event("workflow_creator.boot_missing_deps", {
        hasGetStarters: !!_getStarterWorkflows,
        hasRun:         !!_runWorkflow,
        hasRender:      !!_renderLibrary,
      });
    } catch (_) {}
    return;
  }

  // Kill switch — admin can disable via admin-overrides.json
  try {
    eli.settings.register("workflow_creator_enabled", {
      default: true, type: "boolean", adminPushable: true,
      describe: "Workflow Creator tile + runner enabled",
    });
  } catch (_) {}

  // User-saved workflows + last-run timestamps live in the shared
  // "config" store (canonical key-value bucket used by ~30 other
  // tools). Prefixed with "wf_" to avoid id collisions; CLAUDE.md
  // reserves leading underscore for kernel/internal metadata, so we
  // start with a letter.
  var STORE_CONFIG  = "config";
  var WF_KEY_PREFIX = "wf_";
  var LAST_RUN_KEY  = "wf_last_runs"; // map of { workflowId: ts }

  function _loadUserWorkflows() {
    return eli.storage.getAll(STORE_CONFIG).then(function (rows) {
      return (rows || []).filter(function (r) {
        // Must be a user workflow row: wf_-prefixed AND not the
        // last-runs meta row AND has an actual workflow payload.
        if (!r || typeof r !== "object" || !r.id) return false;
        var id = String(r.id);
        if (id.indexOf(WF_KEY_PREFIX) !== 0) return false;
        if (id === LAST_RUN_KEY) return false;
        return !!r.workflow;
      }).map(function (r) { return r.workflow; });
    }).catch(function () { return []; });
  }
  function _saveUserWorkflow(wf) {
    var key = WF_KEY_PREFIX + wf.id;
    return eli.storage.put(STORE_CONFIG, { id: key, workflow: wf, updatedAt: Date.now() });
  }
  function _deleteUserWorkflow(wfId) {
    return eli.storage.delete(STORE_CONFIG, WF_KEY_PREFIX + wfId);
  }
  function _loadLastRuns() {
    return eli.storage.get(STORE_CONFIG, LAST_RUN_KEY).then(function (row) {
      return (row && row.runs) || {};
    }).catch(function () { return {}; });
  }
  function _stampLastRun(wfId) {
    _loadLastRuns().then(function (runs) {
      runs[wfId] = Date.now();
      eli.storage.put(STORE_CONFIG, { id: LAST_RUN_KEY, runs: runs });
    });
  }

  // ─── Open / library view ────────────────────────────────────────
  function _openLibrary() {
    // FSM goes idle → scanning → rendering, never idle → rendering.
    // Guarded + wrapped because the kernel rejects illegal jumps
    // (e.g. when re-entered from running view, current = "rendering").
    try {
      if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") {
        eli.fsm.transition("scanning");
      }
    } catch (_) {}
    var mount = eli.ui && eli.ui.claimOutput
      ? eli.ui.claimOutput()
      : document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    Promise.all([
      Promise.resolve(_getStarterWorkflows()),
      _loadUserWorkflows(),
      _loadLastRuns(),
    ]).then(function (results) {
      _renderLibrary({
        mount: mount,
        starters: results[0],
        userWorkflows: results[1],
        lastRuns: results[2],
        onRun:    _onRun,
        onEdit:   _onEdit,
        onClone:  _onClone,
        onDelete: _onDelete,
        onNew:    _onNew,
        onBack:   _onBack,
      });
      try { eli.fsm.transition("idle"); } catch (_) {}
    });
  }

  // ─── Read doc context (text + meta) for the workflow runner ─────
  function _readDocContext() {
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve({ docText: "", docHash: "", hasRedlines: false, hasComments: false, commentCount: 0 });
    }
    return eli.host.runRaw("workflow_creator:read_doc", function (context) {
      var body = context.document.body;
      body.load("text");
      var sel = context.document.getSelection();
      sel.load("text");
      var ooxmlResult = body.getOoxml();
      // Comments — best-effort via the new API surfaces.
      var doc = context.document;
      var commentColl = null;
      try {
        if (doc.comments) commentColl = doc.comments;
        else if (doc.body && typeof doc.body.getComments === "function") commentColl = doc.body.getComments();
      } catch (_) {}
      if (commentColl) {
        try { commentColl.load("items/authorName"); } catch (_) { commentColl = null; }
      }
      return context.sync().then(function () {
        var text = String(body.text || "");
        var ooxml = String((ooxmlResult && ooxmlResult.value) || "");
        var hasRedlines = /<w:(ins|del|moveFrom|moveTo)\b/.test(ooxml);
        var commentCount = (commentColl && commentColl.items && commentColl.items.length) || 0;
        return {
          docText: text,
          docHash: _hashString(text),
          selectionText: String((sel && sel.text) || ""),
          hasRedlines: hasRedlines,
          hasComments: commentCount > 0,
          commentCount: commentCount,
          agreementType: window._eliDocType || "Unknown",
        };
      });
    }).catch(function () {
      return { docText: "", docHash: "", hasRedlines: false, hasComments: false, commentCount: 0 };
    });
  }
  function _hashString(s) {
    var h = 0, n = String(s || "").length;
    for (var i = 0; i < n; i++) { h = ((h << 5) - h) + s.charCodeAt(i); h |= 0; }
    return String(h);
  }

  // ─── Run a workflow against the active document ──────────────────
  var _cancelled = false;
  function _onRun(workflow, _isUser) {
    try {
      if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") {
        eli.fsm.transition("scanning");
      }
    } catch (_) {}
    var mount = eli.ui && eli.ui.claimOutput
      ? eli.ui.claimOutput()
      : document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    _cancelled = false;
    var runner = _renderRunner({
      mount: mount,
      workflow: workflow,
      onCancel: function () { _cancelled = true; },
    });
    if (!runner) return;
    _readDocContext().then(function (initialCtx) {
      var providers = {
        ai: eli.ai,
        host: eli.host,
        dispatch: eli.dispatch,
        cancelled: function () { return _cancelled; },
        onProgress: function (ev) {
          runner.updateStep(ev.stepIdx, ev.status, ev.output);
        },
      };
      try { eli.fsm.transition("rendering"); } catch (_) {}
      return _runWorkflow(workflow, initialCtx, providers).then(function (out) {
        if (_cancelled) {
          try { eli.fsm.transition("cancelled"); } catch (_) {}
          setTimeout(_openLibrary, 250);
          return;
        }
        var report = _buildReport(workflow, out.context);
        _stampLastRun(workflow.id);
        try {
          eli.activity.add({
            type: "workflow_run",
            label: "Ran workflow: " + workflow.name,
            ts: Date.now(),
            payload: { workflowId: workflow.id, stepCount: out.results.length },
          });
        } catch (_) {}
        _renderResult({
          mount: mount,
          workflow: workflow,
          report: report,
          results: out.results,
          context: out.context,
          completedAt: out.completedAt,
          onBack:  _openLibrary,
          onRerun: function () { _onRun(workflow); },
          onCopy:  _onCopyReport,
        });
        try { eli.fsm.transition("idle"); } catch (_) {}
      });
    }).catch(function (err) {
      try { eli.log.event("workflow_creator.run_failed", { msg: err && err.message }); } catch (_) {}
      try { eli.fsm.transition("error"); } catch (_) {}
      var errMount = mount;
      errMount.innerHTML = '<div class="_eli3_wf_root"><div class="_eli3_wf_body"><div class="_eli3_wf_error">Workflow failed: ' + ((err && err.message) || "unknown") + '</div></div></div>';
    });
  }

  // ─── Copy report to clipboard as markdown ────────────────────────
  function _onCopyReport(report) {
    var lines = [];
    lines.push("# " + (report.title || "Workflow Result"));
    lines.push("");
    (report.sections || []).forEach(function (s) {
      lines.push("**" + s.label + ":** " + s.value);
      if (s.note) lines.push("_" + s.note + "_");
      lines.push("");
    });
    if (report.listItems && report.listItems.length) {
      lines.push("## Details");
      report.listItems.forEach(function (item) {
        lines.push("- **" + (item.title || "—") + "**" + (item.badge != null ? " [" + item.badge + "]" : "") + (item.meta ? " _(" + item.meta + ")_" : ""));
        if (item.body) lines.push("  " + item.body);
      });
    }
    var md = lines.join("\n");
    try {
      navigator.clipboard.writeText(md).then(function () {
        if (typeof window.showToast === "function") {
          window.showToast("Copied to clipboard as Markdown");
        }
      });
    } catch (_) {}
  }

  // ─── Edit / view ────────────────────────────────────────────────
  function _onEdit(workflow, isUser) {
    var mount = eli.ui && eli.ui.claimOutput
      ? eli.ui.claimOutput()
      : document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    _renderEditor({
      mount: mount,
      workflow: workflow,
      readOnly: !isUser,
      onSave: function (wf) {
        var errs = _validateWorkflow(wf);
        if (errs.length) {
          alert("Workflow has issues:\n\n" + errs.join("\n"));
          return;
        }
        _saveUserWorkflow(wf).then(_openLibrary);
      },
      onCancel: _openLibrary,
      onTestStep: function (step, _wf) {
        // Test a single step against the current doc
        _readDocContext().then(function (ctx) {
          var providers = {
            ai: eli.ai, host: eli.host, dispatch: eli.dispatch,
            cancelled: function () { return false; },
            onProgress: function () {},
          };
          return _runWorkflow({ id: "test", name: "Test", steps: [step] }, ctx, providers);
        }).then(function (out) {
          var output = out.results[0] && out.results[0].output;
          alert("Test output:\n\n" + JSON.stringify(output, null, 2));
        });
      },
    });
  }

  function _onClone(workflow) {
    var clone = JSON.parse(JSON.stringify(workflow));
    clone.id = workflow.id + "_clone_" + Date.now();
    clone.name = workflow.name + " (clone)";
    _saveUserWorkflow(clone).then(_openLibrary);
  }
  function _onDelete(workflow) {
    if (!confirm("Delete workflow \"" + workflow.name + "\"? This cannot be undone.")) return;
    _deleteUserWorkflow(workflow.id).then(_openLibrary);
  }
  function _onNew() {
    _renderEditor({
      mount: eli.ui && eli.ui.claimOutput ? eli.ui.claimOutput() : document.getElementById("_eli3_dashboard_root"),
      workflow: null,
      readOnly: false,
      onSave: function (wf) {
        var errs = _validateWorkflow(wf);
        if (errs.length) {
          alert("Workflow has issues:\n\n" + errs.join("\n"));
          return;
        }
        _saveUserWorkflow(wf).then(_openLibrary);
      },
      onCancel: _openLibrary,
      onTestStep: function () { alert("Save the workflow first, then test individual steps from the edit view."); },
    });
  }
  function _onBack() {
    try { eli.fsm.transition("idle"); } catch (_) {}
    if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
    else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
  }

  // ─── Tile registration ───────────────────────────────────────────
  eli.register({
    tile: { app_workflow_creator: _openLibrary },
    tile_settings: { app_workflow_creator: _openLibrary },
    workflow_creator: { open: _openLibrary, runById: function (wfId) {
      Promise.all([Promise.resolve(_getStarterWorkflows()), _loadUserWorkflows()]).then(function (rs) {
        var all = rs[0].concat(rs[1]);
        var wf = all.find ? all.find(function (w) { return w.id === wfId; }) : null;
        if (wf) _onRun(wf);
      });
    }},
  });
}

jsonTools.css:
/* workflow_creator — premium navy/gold palette
   Light tool view in both themes (per CLAUDE.md tools+dialogs rule). */

._eli3_wf_root {
  font: 13px/1.5 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0;
  min-height: 100vh;
  box-sizing: border-box;
  flex: 1 0 auto;
}
.beta-ui-active .output-area:has(> ._eli3_wf_root),
.output-area:has(> ._eli3_wf_root) {
  background: #f8fafc !important;
}

/* ── HEADER — navy gradient with gold accent line ─────────────────── */
._eli3_wf_header {
  background: linear-gradient(135deg, #020617 0%, #1e3a8a 100%);
  color: #f1f5f9;
  padding: 18px 20px 16px;
  border-bottom: 3px solid #c9a227;
  position: relative;
}
._eli3_wf_header_eyebrow {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 2.5px;
  color: #c9a227;
  margin-bottom: 6px;
}
._eli3_wf_header_title {
  font: 700 22px/1.15 'Georgia', serif;
  margin: 0;
  letter-spacing: 0.3px;
}
._eli3_wf_header_sub {
  font-size: 12px;
  color: #cbd5e1;
  margin-top: 4px;
  line-height: 1.4;
}
._eli3_wf_header_actions {
  margin-top: 12px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

/* ── Buttons ──────────────────────────────────────────────────────── */
._eli3_wf_btn {
  font: 600 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 8px 14px;
  border-radius: 4px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}
._eli3_wf_btn_gold {
  background: linear-gradient(180deg, #d4ac34 0%, #c9a227 100%);
  color: #0f172a;
  border-color: #b8901f;
  box-shadow: 0 1px 0 rgba(255,255,255,0.4) inset, 0 1px 2px rgba(0,0,0,0.15);
}
._eli3_wf_btn_gold:hover {
  background: linear-gradient(180deg, #e0b939 0%, #d4ac34 100%);
  transform: translateY(-1px);
  box-shadow: 0 1px 0 rgba(255,255,255,0.4) inset, 0 2px 4px rgba(0,0,0,0.2);
}
._eli3_wf_btn_platinum {
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  color: #0f172a;
  border-color: #cbd5e1;
}
._eli3_wf_btn_platinum:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border-color: #94a3b8;
}
._eli3_wf_btn_ghost {
  background: rgba(255,255,255,0.10);
  color: #cbd5e1;
  border-color: rgba(255,255,255,0.20);
}
._eli3_wf_btn_ghost:hover {
  background: rgba(201,162,39,0.25);
  color: #f2d866;
  border-color: rgba(201,162,39,0.5);
}
._eli3_wf_btn_danger {
  background: linear-gradient(180deg, #fee2e2 0%, #fecaca 100%);
  color: #991b1b;
  border-color: #fca5a5;
}
._eli3_wf_btn_danger:hover {
  background: linear-gradient(180deg, #fecaca 0%, #fca5a5 100%);
}
._eli3_wf_btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }

/* ── BODY ─────────────────────────────────────────────────────────── */
._eli3_wf_body {
  padding: 16px;
}

/* ── Library list view ────────────────────────────────────────────── */
._eli3_wf_section_label {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #64748b;
  padding: 4px 0 8px;
  border-bottom: 1px solid #e2e8f0;
  margin: 16px 0 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
._eli3_wf_section_label:first-child { margin-top: 0; }
._eli3_wf_count_chip {
  background: #f1f5f9;
  color: #475569;
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 10px;
  letter-spacing: 0;
}

._eli3_wf_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #c9a227;
  border-radius: 4px;
  padding: 14px 16px;
  margin-bottom: 10px;
  position: relative;
  transition: all 0.15s;
}
._eli3_wf_card:hover {
  border-color: #cbd5e1;
  border-left-color: #c9a227;
  box-shadow: 0 2px 6px rgba(15,23,42,0.06);
  transform: translateY(-1px);
}
._eli3_wf_card_user {
  border-left-color: #1565c0;
}
._eli3_wf_card_head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 4px;
}
._eli3_wf_card_icon {
  font-size: 24px;
  flex-shrink: 0;
  line-height: 1;
  margin-top: 1px;
}
._eli3_wf_card_titles {
  flex: 1;
  min-width: 0;
}
._eli3_wf_card_name {
  font: 700 14px/1.3 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_wf_card_desc {
  font-size: 12px;
  color: #64748b;
  line-height: 1.45;
  margin-top: 2px;
}
._eli3_wf_card_meta {
  font: 600 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #94a3b8;
  margin-top: 8px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
._eli3_wf_card_meta span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
._eli3_wf_card_actions {
  display: flex;
  gap: 6px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid #f1f5f9;
}
._eli3_wf_tag {
  display: inline-block;
  background: #f8fafc;
  color: #475569;
  font: 600 9px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 3px 6px;
  border-radius: 3px;
  border: 1px solid #e2e8f0;
  margin-right: 4px;
}

/* ── Running view ─────────────────────────────────────────────────── */
._eli3_wf_runner {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 18px;
  margin-bottom: 12px;
}
._eli3_wf_runner_title {
  font: 700 16px/1.2 'Georgia', serif;
  color: #0f172a;
  margin: 0 0 6px;
}
._eli3_wf_runner_progress {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #64748b;
  margin-bottom: 14px;
}
._eli3_wf_step_row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 4px;
  margin-bottom: 4px;
  background: #f8fafc;
  transition: all 0.15s;
}
._eli3_wf_step_row._eli3_wf_step_done    { background: #ecfdf5; }
._eli3_wf_step_row._eli3_wf_step_running { background: #fef9c3; border: 1px solid #facc15; padding: 7px 9px; }
._eli3_wf_step_row._eli3_wf_step_error   { background: #fee2e2; }
._eli3_wf_step_indicator {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #cbd5e1;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  flex-shrink: 0;
}
._eli3_wf_step_done    ._eli3_wf_step_indicator { background: #10b981; }
._eli3_wf_step_running ._eli3_wf_step_indicator { background: #c9a227; animation: _eli3_wf_pulse 1.2s ease-in-out infinite; }
._eli3_wf_step_error   ._eli3_wf_step_indicator { background: #dc2626; }
@keyframes _eli3_wf_pulse {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(201,162,39,0.5); }
  50%      { transform: scale(1.08); box-shadow: 0 0 0 6px rgba(201,162,39,0); }
}
._eli3_wf_step_name {
  flex: 1;
  font-size: 13px;
  color: #0f172a;
  font-weight: 500;
}
._eli3_wf_step_type {
  font: 600 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #94a3b8;
  background: #fff;
  padding: 3px 6px;
  border-radius: 3px;
  border: 1px solid #e2e8f0;
}

/* ── Result view ──────────────────────────────────────────────────── */
._eli3_wf_result_banner {
  background: linear-gradient(135deg, #f8fafc 0%, #fffbeb 100%);
  border: 1px solid #e2e8f0;
  border-left: 4px solid #c9a227;
  border-radius: 6px;
  padding: 16px 18px;
  margin-bottom: 14px;
}
._eli3_wf_result_eyebrow {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #c9a227;
  margin-bottom: 4px;
}
._eli3_wf_result_title {
  font: 700 18px/1.2 'Georgia', serif;
  color: #0f172a;
  margin: 0;
}
._eli3_wf_result_meta {
  font-size: 11px;
  color: #64748b;
  margin-top: 6px;
  letter-spacing: 0.3px;
}

._eli3_wf_section {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 14px 16px;
  margin-bottom: 10px;
}
._eli3_wf_section_emphasis {
  background: #fffbeb;
  border-color: #fde68a;
  border-left: 3px solid #c9a227;
}
._eli3_wf_section_lbl {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.3px;
  color: #64748b;
  margin-bottom: 4px;
}
._eli3_wf_section_val {
  font: 600 14px/1.4 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_wf_section_emphasis ._eli3_wf_section_val {
  font: 600 16px/1.4 'Georgia', serif;
  color: #1e3a8a;
}
._eli3_wf_section_note {
  font-size: 12px;
  color: #64748b;
  margin-top: 4px;
  line-height: 1.45;
  font-style: italic;
}

._eli3_wf_list_item {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
  padding: 10px 12px;
  margin-bottom: 6px;
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
._eli3_wf_list_severity {
  width: 4px;
  align-self: stretch;
  background: #cbd5e1;
  border-radius: 2px;
  flex-shrink: 0;
}
._eli3_wf_list_severity[data-sev="high"]   { background: #dc2626; }
._eli3_wf_list_severity[data-sev="medium"] { background: #f59e0b; }
._eli3_wf_list_severity[data-sev="low"]    { background: #10b981; }
._eli3_wf_list_body {
  flex: 1;
}
._eli3_wf_list_head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
._eli3_wf_list_title {
  font: 600 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_wf_list_badge {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  background: #f1f5f9;
  color: #475569;
  padding: 3px 6px;
  border-radius: 3px;
  border: 1px solid #e2e8f0;
}
._eli3_wf_list_meta {
  font-size: 10px;
  color: #94a3b8;
  margin-top: 2px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
._eli3_wf_list_text {
  font-size: 12px;
  color: #475569;
  line-height: 1.5;
  margin-top: 6px;
}

/* ── Editor view ──────────────────────────────────────────────────── */
._eli3_wf_editor_section {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 14px;
  margin-bottom: 10px;
}
._eli3_wf_editor_label {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: #64748b;
  margin-bottom: 4px;
  display: block;
}
._eli3_wf_editor_input,
._eli3_wf_editor_textarea,
._eli3_wf_editor_select {
  width: 100%;
  font: 13px/1.5 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  padding: 8px 10px;
  box-sizing: border-box;
}
._eli3_wf_editor_input:focus,
._eli3_wf_editor_textarea:focus,
._eli3_wf_editor_select:focus {
  outline: none;
  border-color: #c9a227;
  box-shadow: 0 0 0 2px rgba(201,162,39,0.2);
}
._eli3_wf_editor_textarea {
  font-family: 'JetBrains Mono', Menlo, 'Courier New', monospace;
  font-size: 12px;
  resize: vertical;
  min-height: 80px;
}
._eli3_wf_step_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #94a3b8;
  border-radius: 4px;
  padding: 12px;
  margin-bottom: 8px;
  position: relative;
}
._eli3_wf_step_card._eli3_wf_step_ask_ai    { border-left-color: #1565c0; }
._eli3_wf_step_card._eli3_wf_step_read_doc  { border-left-color: #10b981; }
._eli3_wf_step_card._eli3_wf_step_extract   { border-left-color: #c9a227; }
._eli3_wf_step_card._eli3_wf_step_transform { border-left-color: #8b5cf6; }
._eli3_wf_step_card._eli3_wf_step_branch    { border-left-color: #f59e0b; }
._eli3_wf_step_card._eli3_wf_step_run_tool  { border-left-color: #dc2626; }
._eli3_wf_step_card._eli3_wf_step_email     { border-left-color: #6366f1; }
._eli3_wf_step_card._eli3_wf_step_report    { border-left-color: #475569; }

._eli3_wf_step_card_head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}
._eli3_wf_step_idx {
  background: #0f172a;
  color: #fff;
  font: 700 11px/1 'Inter', sans-serif;
  padding: 4px 8px;
  border-radius: 3px;
  flex-shrink: 0;
}
._eli3_wf_step_card_name {
  flex: 1;
  font: 600 13px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_wf_step_card_actions {
  display: flex;
  gap: 4px;
}
._eli3_wf_step_iconbtn {
  background: transparent;
  border: 1px solid #cbd5e1;
  border-radius: 3px;
  padding: 4px 6px;
  font-size: 11px;
  cursor: pointer;
  color: #64748b;
  transition: all 0.15s;
}
._eli3_wf_step_iconbtn:hover {
  background: #f1f5f9;
  color: #0f172a;
}
._eli3_wf_step_iconbtn_danger:hover {
  background: #fee2e2;
  color: #991b1b;
  border-color: #fca5a5;
}
._eli3_wf_step_field {
  margin-top: 8px;
}
._eli3_wf_step_field_lbl {
  font: 600 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #64748b;
  display: block;
  margin-bottom: 3px;
}
._eli3_wf_vars_hint {
  font-size: 11px;
  color: #64748b;
  background: #f8fafc;
  border: 1px dashed #cbd5e1;
  padding: 6px 10px;
  border-radius: 4px;
  margin-top: 6px;
  font-family: 'JetBrains Mono', monospace;
}
._eli3_wf_vars_hint code {
  background: #fff;
  padding: 1px 4px;
  border-radius: 2px;
  border: 1px solid #e2e8f0;
  color: #c9a227;
}

._eli3_wf_add_step {
  background: #f8fafc;
  border: 2px dashed #cbd5e1;
  border-radius: 6px;
  padding: 16px;
  text-align: center;
  cursor: pointer;
  color: #64748b;
  font: 600 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-top: 8px;
  transition: all 0.15s;
}
._eli3_wf_add_step:hover {
  background: #fffbeb;
  border-color: #c9a227;
  color: #c9a227;
}

/* ── Empty + error states ─────────────────────────────────────────── */
._eli3_wf_empty {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 32px 20px;
  text-align: center;
  color: #94a3b8;
}
._eli3_wf_empty_icon { font-size: 32px; margin-bottom: 8px; opacity: 0.5; }
._eli3_wf_empty_msg { font-size: 13px; }

._eli3_wf_error {
  background: #fee2e2;
  border: 1px solid #fca5a5;
  color: #991b1b;
  border-radius: 4px;
  padding: 10px 12px;
  font-size: 12px;
  margin-bottom: 10px;
}

/* ── Raw step output expandable ───────────────────────────────────── */
._eli3_wf_raw_output {
  background: #0f172a;
  color: #c9a227;
  border-radius: 4px;
  padding: 10px 12px;
  font: 11px/1.5 'JetBrains Mono', Menlo, monospace;
  white-space: pre-wrap;
